CREATE TABLE IF NOT EXISTS invite_codes (code_hash TEXT PRIMARY KEY CHECK(length(code_hash)=43 AND code_hash NOT GLOB '*[^A-Za-z0-9_-]*'), created_at INTEGER NOT NULL CHECK(created_at>=0), expires_at INTEGER NOT NULL CHECK(expires_at>=created_at), used_at INTEGER, publisher_id TEXT REFERENCES publishers(id), CHECK((used_at IS NULL AND publisher_id IS NULL) OR (used_at IS NOT NULL AND publisher_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS api_tokens (token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=43 AND token_hash NOT GLOB '*[^A-Za-z0-9_-]*'), publisher_id TEXT NOT NULL REFERENCES publishers(id), created_at INTEGER NOT NULL CHECK(created_at>=0), last_used_bucket INTEGER CHECK(last_used_bucket IS NULL OR (last_used_bucket>=0 AND last_used_bucket%86400000=0)), revoked_at INTEGER CHECK(revoked_at IS NULL OR revoked_at>=0));
INSERT INTO invite_codes(code_hash,created_at,expires_at,used_at,publisher_id) SELECT i.codeHash,i.createdAt,i.expiresAt,i.usedAt,p.id FROM publisher_invites i LEFT JOIN publishers p ON p.key_id=i.usedByPublisherKeyId WHERE 1 ON CONFLICT(code_hash) DO UPDATE SET expires_at=CASE WHEN invite_codes.created_at=excluded.created_at AND invite_codes.expires_at=excluded.expires_at AND invite_codes.used_at IS excluded.used_at AND invite_codes.publisher_id IS excluded.publisher_id THEN invite_codes.expires_at ELSE -1 END;
INSERT INTO api_tokens(token_hash,publisher_id,created_at,last_used_bucket,revoked_at) SELECT e.tokenHash,p.id,e.enrolledAt,NULL,e.revokedAt FROM publisher_enrollments e JOIN publishers p ON p.key_id=e.publisherKeyId WHERE 1 ON CONFLICT(token_hash) DO UPDATE SET created_at=CASE WHEN api_tokens.publisher_id=excluded.publisher_id AND api_tokens.created_at=excluded.created_at AND api_tokens.revoked_at IS excluded.revoked_at THEN api_tokens.created_at ELSE -1 END;
